arguments.new_string:
server {
    listen 8443 ssl;
    server_name localhost;

    ssl_certificate /etc/ssl/certs/nginx-selfsigned.crt;
    ssl_certificate_key /etc/ssl/private/nginx-selfsigned.key;

    root /var/www/main;
    index index.html;

    location = /dev {
        return 301 /dev/;
    }

    location ^~ /dev/ {
        alias /var/www/dev/;
        index index.html;
    }

    location / {
        try_files $uri $uri/ =404;
    }
}

